style.css:
@-moz-document domain("axiom.trade") {
/* Set the background image using the install key */
    body {
        background-image: url('/*[[bg_img]]*/');
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
    }

    /* Apply frosted glass effect to the panels */
    .panel-class-name {
        background-color: rgba(255, 255, 255, 0.2); /* Semi-transparent white (more see-through) */
        backdrop-filter: blur(10px); /* Frosted glass blur effect */
        border-radius: 10px; /* Rounded corners */
        padding: 20px; /* Add some padding */
        border: 1px solid rgba(255, 255, 255, 0.3); /* Light border for subtle definition */
        box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); /* Soft shadow for depth */
    }

    /* Ensure text inside the panels is readable */
    .panel-class-name h1,
    .panel-class-name h2,
    .panel-class-name h3,
    .panel-class-name p {
        color: #ffffff; /* White text */
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Text shadow for better readability */
    }
}

